class Solution {
public:
    int maximizeSweetness(vector<int>& sweetness, int k) {
        int low = 1;
        int high = accumulate(sweetness.begin(), sweetness.end(), 0) / (k + 1);
        int answer = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int pieces = 0;
            int current = 0;
            for (int value : sweetness) {
                current += value;
                if (current >= mid) {
                    ++pieces;
                    current = 0;
                }
            }
            if (pieces >= k + 1) {
                answer = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }
};
